import{_ as i,a0 as l,w as r,s as h,ao as o,I as p,x as a,a1 as e,A as t}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const P=JSON.parse('{"title":"結合使用 Python 和 Rust | LCTT x X-CMD","titleTemplate":false,"description":"結合使用 Python 和 Rust | LCTT (202305) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"結合使用 Python 和 Rust | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"結合使用 Python 和 Rust | LCTT (202305) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202305/20230328.3 ⭐️⭐️ Why you should use Python and Rust together","title":"結合使用 Python 和 Rust","tag":"202305","desc":""},"relativePath":"202305/20230328.3 ⭐️⭐️ Why you should use Python and Rust together.md","filePath":"[post].md"}'),c={name:"202305/20230328.3 ⭐️⭐️ Why you should use Python and Rust together.md"};function d(u,s,g,b,k,y){const n=l("Link");return r(),h("div",null,[s[13]||(s[13]=o(`<h1 id="結合使用-python-和-rust" tabindex="-1">結合使用 Python 和 Rust <a class="header-anchor" href="#結合使用-python-和-rust" aria-label="Permalink to “結合使用 Python 和 Rust”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202305/26/163350snf627fx05ynz71j.jpg" alt=""></p><blockquote><p>Rust 和 Python 的優勢互補。可以使用 Python 進行原型設計，然後將性能瓶頸轉移到 Rust 上。</p></blockquote><p>Python 和 Rust 是非常不同的語言，但它們實際上非常搭配。但在討論如何將 Python 與 Rust 結合之前，我想先介紹一下 Rust 本身。你可能已經聽説了這種語言，但可能還沒有了解過它的細節。</p><h3 id="什麼是-rust" tabindex="-1">什麼是 Rust？ <a class="header-anchor" href="#什麼是-rust" aria-label="Permalink to “什麼是 Rust？”">​</a></h3><p>Rust 是一種低級語言，這意味着程序員所處理的東西接近於計算機的 “真實” 運行方式。</p><p>例如，整數類型由字節大小定義，與 CPU 支持的類型相對應。雖然我們很想簡單地説 Rust 中的 <code>a+b</code> 對應於一條機器指令，但實際上並不完全是這樣！</p><p>Rust 編譯器鏈非常複雜。作為第一種近似的方法，將這樣的語句視為 “有點” 真實是有用的。</p><p>Rust 旨在實現零成本抽象，這意味着許多語言級別可用的抽象在運行時環境中會被編譯去掉。</p><p>例如，除非明確要求，對象會在堆棧上分配。結果是，在 Rust 中創建本地對象沒有運行時成本（儘管可能需要進行初始化）。</p><p>最後，Rust 是一種內存安全的語言。也有其他內存安全的語言和其他支持零成本抽象的語言。但通常這些是兩類不同的語言。</p><p>內存安全並不意味着不可能在 Rust 中出現內存違規。它確實意味着只有兩種方式可能導致內存違規：</p><ul><li>編譯器的錯誤。</li><li>顯式聲明為不安全（<code>unsafe</code>）的代碼。</li></ul><p>Rust 標準庫代碼有很多被標記為不安全的代碼，雖然比許多人預期的少。這並不意味着該語句無意義。除了需要自己編寫不安全代碼的（罕見的）情況外，內存違規通常是由基礎設施造成的。</p><h3 id="為什麼會有-rust-出現" tabindex="-1">為什麼會有 Rust 出現？ <a class="header-anchor" href="#為什麼會有-rust-出現" aria-label="Permalink to “為什麼會有 Rust 出現？”">​</a></h3><p>為什麼人們要創建 Rust？是哪些問題沒有被現有編程語言解決嗎？</p><p>Rust 被設計成既能高效運行，又保證內存安全。在現代的聯網世界中，這是一個越來越重要的問題。</p><p>Rust 的典型應用場景是協議的低級解析。待解析的數據通常來自不受信任的來源，並且需要通過高效的方式進行解析。</p><p>如果你認為這聽起來像 Web 瀏覽器所做的事情，那不是巧合。Rust 最初起源於 Mozilla 基金會，它是為了改進 Firefox 瀏覽器而設計的。</p><p>如今，需要保證安全和速度的不僅僅是瀏覽器。即使是常見的微服務架構也必須能夠快速解析不受信任的數據，同時保證安全。</p><h3 id="現實示例-統計字符" tabindex="-1">現實示例：統計字符 <a class="header-anchor" href="#現實示例-統計字符" aria-label="Permalink to “現實示例：統計字符”">​</a></h3><p>為了理解 “封裝 Rust” 的例子，需要解決一個問題。這個問題需要滿足以下要求：</p><ul><li>足夠容易解決。</li><li>能夠寫高性能循環來優化。</li><li>有一定的現實意義。</li></ul><p>這個玩具問題的例子是判斷一個字符在一個字符串中是否出現超過了 X 次。這個問題不容易通過高效的正則表達式解決。即使是專門的 Numpy 代碼也可能不夠快，因為通常沒有必要掃描整個字符串。</p><p>你可以想像一些 Python 庫和技巧的組合來解決這個問題。然而，如果在低級別的語言中實現直接的算法，它會非常快，並且更易於閲讀。</p><p>為了使問題稍微有趣一些，以演示 Rust 的一些有趣部分，這個問題增加了一些變化。該算法支持在換行符處重置計數（意即：字符是否在一行中出現了超過 X 次？）或在空格處重置計數（意即：字符是否在單詞中出現了超過 X 次？）。</p><p>這是唯一與 “現實性” 相關的部分。過多的現實性將使這個示例在教育上不再有用。</p><h4 id="支持枚舉" tabindex="-1">支持枚舉 <a class="header-anchor" href="#支持枚舉" aria-label="Permalink to “支持枚舉”">​</a></h4><p>Rust 支持使用枚舉（<code>enum</code>）。你可以使用枚舉做很多有趣的事情。</p><p>目前，只使用了一個簡單的三選一的枚舉，並沒有其他的變形。這個枚舉編碼了哪種字符重置計數。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>#[derive(Copy)]</span></span>
<span class="line"><span>enum Reset {</span></span>
<span class="line"><span>    NewlinesReset,</span></span>
<span class="line"><span>    SpacesReset,</span></span>
<span class="line"><span>    NoReset,</span></span>
<span class="line"><span>}</span></span></code></pre></div><h4 id="支持結構" tabindex="-1">支持結構 <a class="header-anchor" href="#支持結構" aria-label="Permalink to “支持結構”">​</a></h4><p>接下來的 Rust 組件更大一些：這是一個結構（<code>struct</code>）。Rust 的結構與 Python 的 <code>dataclass</code> 有些相似。同樣，你可以用結構做更復雜的事情。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>#[pyclass]</span></span>
<span class="line"><span>struct Counter {</span></span>
<span class="line"><span>    what: char,</span></span>
<span class="line"><span>    min_number: u64,</span></span>
<span class="line"><span>    reset: Reset, </span></span>
<span class="line"><span>}</span></span></code></pre></div><h4 id="實現塊" tabindex="-1">實現塊 <a class="header-anchor" href="#實現塊" aria-label="Permalink to “實現塊”">​</a></h4><p>你可以在 Rust 中使用一個單獨的塊，稱為實現（<code>impl</code>）塊，為結構添加一個方法。但具體細節超出了本文的範圍。</p><p>在這個示例中，該方法調用了一個外部函數。這主要是為了分解代碼。更復雜的用例將指示 Rust 編譯器內聯該函數，以便在不產生任何運行時成本的情況下提高可讀性。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>#[pymethods]</span></span>
<span class="line"><span>impl Counter {</span></span>
<span class="line"><span>    #[new]</span></span>
<span class="line"><span>    fn new(what: char, min_number: u64, reset: Reset) -&gt; Self {</span></span>
<span class="line"><span>        Counter{what: what, min_number: min_number, reset: reset}</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>    </span></span>
<span class="line"><span>    fn has_count(</span></span>
<span class="line"><span>        &amp;self,</span></span>
<span class="line"><span>        data: &amp;str,</span></span>
<span class="line"><span>    ) -&gt; bool {</span></span>
<span class="line"><span>        has_count(self, data.chars())</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre></div><h4 id="函數" tabindex="-1">函數 <a class="header-anchor" href="#函數" aria-label="Permalink to “函數”">​</a></h4><p>默認情況下，Rust 變量是常量。由於當前的計數（<code>current_count</code>）必須更改，因此它被聲明為可變變量。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>fn has_count(cntr: &amp;Counter, chars: std::str::Chars) -&gt; bool {</span></span>
<span class="line"><span>    let mut current_count : u64 = 0;</span></span>
<span class="line"><span>    for c in chars {</span></span>
<span class="line"><span>        if got_count(cntr, c, &amp;mut current_count) {</span></span>
<span class="line"><span>            return true;</span></span>
<span class="line"><span>        }</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>    false</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>該循環遍歷字符並調用 <code>got_count</code> 函數。再次強調，這是為了將代碼分解成幻燈片展示。它展示瞭如何向函數發送可變引用。</p><p>儘管 <code>current_count</code> 是可變的，但發送和接收站點都顯式標記該引用為可變。這可以清楚地表明哪些函數可能修改一個值。</p><h4 id="計數" tabindex="-1">計數 <a class="header-anchor" href="#計數" aria-label="Permalink to “計數”">​</a></h4><p><code>got_count</code> 函數重置計數器，將其遞增，然後檢查它。Rust 的冒號分隔的表達式序列評估最後一個表達式的結果，即是否達到了指定的閾值。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>fn got_count(cntr: &amp;Counter, c: char, current_count: &amp;mut u64) -&gt; bool {</span></span>
<span class="line"><span>    maybe_reset(cntr, c, current_count);</span></span>
<span class="line"><span>    maybe_incr(cntr, c, current_count);</span></span>
<span class="line"><span>    *current_count &gt;= cntr.min_number</span></span>
<span class="line"><span>}</span></span></code></pre></div><h4 id="重置代碼" tabindex="-1">重置代碼 <a class="header-anchor" href="#重置代碼" aria-label="Permalink to “重置代碼”">​</a></h4><p><code>reset</code> 的代碼展示了 Rust 中另一個有用的功能：模式匹配。對 Rust 中匹配的完整描述需要一個學期級別的課程，不適合在一個無關的演講中講解。這個示例匹配了該元組的兩個選項之一。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>fn maybe_reset(cntr: &amp;Counter, c: char, current_count: &amp;mut u64) -&gt; () {</span></span>
<span class="line"><span>    match (c, cntr.reset) {</span></span>
<span class="line"><span>        (&#39;\\n&#39;, Reset::NewlinesReset) | (&#39; &#39;, Reset::SpacesReset)=&gt; {</span></span>
<span class="line"><span>            *current_count = 0;</span></span>
<span class="line"><span>        }</span></span>
<span class="line"><span>        _ =&gt; {}</span></span>
<span class="line"><span>    };</span></span>
<span class="line"><span>}</span></span></code></pre></div><h4 id="增量支持" tabindex="-1">增量支持 <a class="header-anchor" href="#增量支持" aria-label="Permalink to “增量支持”">​</a></h4><p>增量將字符與所需字符進行比較，並在匹配時增加計數。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>fn maybe_incr(cntr: &amp;Counter, c: char, current_count: &amp;mut u64) -&gt; (){</span></span>
<span class="line"><span>    if c == cntr.what {</span></span>
<span class="line"><span>        *current_count += 1;</span></span>
<span class="line"><span>    };</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>請注意，我在本文中優化了代碼以適合幻燈片。這不一定是 Rust 代碼的最佳實踐示例，也不是如何設計良好的 API 的示例。</p><h3 id="為-python-封裝-rust-代碼" tabindex="-1">為 Python 封裝 Rust 代碼 <a class="header-anchor" href="#為-python-封裝-rust-代碼" aria-label="Permalink to “為 Python 封裝 Rust 代碼”">​</a></h3><p>為了將 Rust 代碼封裝到 Python 中，你可以使用 PyO3。PyO3 Rust “crate”（即庫）允許內聯提示將 Rust 代碼包裝為 Python，使得修改兩者更容易。</p><h4 id="包含-pyo3-crate-原語" tabindex="-1">包含 PyO3 crate 原語 <a class="header-anchor" href="#包含-pyo3-crate-原語" aria-label="Permalink to “包含 PyO3 crate 原語”">​</a></h4><p>首先，你必須包含 PyO3 crate 原語。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>use pyo3::prelude::*;</span></span></code></pre></div><h4 id="封裝枚舉" tabindex="-1">封裝枚舉 <a class="header-anchor" href="#封裝枚舉" aria-label="Permalink to “封裝枚舉”">​</a></h4><p>枚舉需要被封裝。<code>derive</code> 從句對於將枚舉封裝為 PyO3 是必需的，因為它們允許類被複制和克隆，使它們更容易在 Python 中使用。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>#[pyclass]</span></span>
<span class="line"><span>#[derive(Clone)]</span></span>
<span class="line"><span>#[derive(Copy)]</span></span>
<span class="line"><span>enum Reset {</span></span>
<span class="line"><span>    /* ... */</span></span>
<span class="line"><span>}</span></span></code></pre></div><h4 id="封裝結構" tabindex="-1">封裝結構 <a class="header-anchor" href="#封裝結構" aria-label="Permalink to “封裝結構”">​</a></h4><p>結構同樣需要被封裝。在 Rust 中，這些被稱為 “宏”，它們會生成所需的接口位。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>#[pyclass]</span></span>
<span class="line"><span>struct Counter {</span></span>
<span class="line"><span>    /* ... */</span></span>
<span class="line"><span>}</span></span></code></pre></div><h4 id="封裝實現" tabindex="-1">封裝實現 <a class="header-anchor" href="#封裝實現" aria-label="Permalink to “封裝實現”">​</a></h4><p>封裝實現（<code>impl</code>）更有趣。增加了另一個名為 <code>new</code> 的宏。此方法被標記為 <code>#[new]</code>，讓 PyO3 知道如何為內置對象公開構造函數。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>#[pymethods]</span></span>
<span class="line"><span>impl Counter {</span></span>
<span class="line"><span>    #[new]</span></span>
<span class="line"><span>    fn new(what: char, min_number: u64,</span></span>
<span class="line"><span>          reset: Reset) -&gt; Self {</span></span>
<span class="line"><span>        Counter{what: what,</span></span>
<span class="line"><span>          min_number: min_number, reset: reset}</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>    /* ... */</span></span>
<span class="line"><span>}</span></span></code></pre></div><h4 id="定義模組" tabindex="-1">定義模組 <a class="header-anchor" href="#定義模組" aria-label="Permalink to “定義模組”">​</a></h4><p>最後，定義一個初始化模組的函數。此函數具有特定的簽名，必須與模組同名，並用 <code>#[pymodule]</code> 修飾。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>#[pymodule]</span></span>
<span class="line"><span>fn counter(_py: Python, m: &amp;PyModule</span></span>
<span class="line"><span>) -&gt; PyResult&lt;()&gt; {</span></span>
<span class="line"><span>    m.add_class::&lt;Counter&gt;()?;</span></span>
<span class="line"><span>    m.add_class::&lt;Reset&gt;()?;</span></span>
<span class="line"><span>    Ok(())</span></span>
<span class="line"><span>}</span></span></code></pre></div><p><code>?</code> 顯示此函數可能失敗（例如，如果類沒有正確配置）。 <code>PyResult</code> 在導入時轉換為 Python 異常。</p><h4 id="maturin-開發" tabindex="-1">Maturin 開發 <a class="header-anchor" href="#maturin-開發" aria-label="Permalink to “Maturin 開發”">​</a></h4><p>為了快速檢查，用 <code>maturin develop</code> 構建並將庫安裝到當前虛擬環境中。這有助於快速迭代。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ maturin develop</span></span></code></pre></div><h4 id="maturin-構建" tabindex="-1">Maturin 構建 <a class="header-anchor" href="#maturin-構建" aria-label="Permalink to “Maturin 構建”">​</a></h4><p><code>maturin build</code> 命令構建一個 <code>manylinux</code> 輪子，它可以上傳到 PyPI。輪子是特定於 CPU 架構的。</p><h4 id="python-庫" tabindex="-1">Python 庫 <a class="header-anchor" href="#python-庫" aria-label="Permalink to “Python 庫”">​</a></h4><p>從 Python 中使用庫是最簡單的部分。沒有任何東西表明這與在 Python 中編寫代碼有什麼區別。這其中的一個有用方面是，如果你優化了已經有單元測試的 Python 中的現有庫，你可以使用 Python 單元測試來測試 Rust 庫。</p><h4 id="導入" tabindex="-1">導入 <a class="header-anchor" href="#導入" aria-label="Permalink to “導入”">​</a></h4><p>無論你是使用 <code>maturin develop</code> 還是 <code>pip install</code> 來安裝它，導入庫都是使用 <code>import</code> 完成的。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>import counter</span></span></code></pre></div><h4 id="構造函數" tabindex="-1">構造函數 <a class="header-anchor" href="#構造函數" aria-label="Permalink to “構造函數”">​</a></h4><p>構造函數的定義正好使對象可以從 Python 構建。這並不總是如此。有時僅從更復雜的函數返回對象。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>cntr = counter.Counter(</span></span>
<span class="line"><span>    &#39;c&#39;,</span></span>
<span class="line"><span>    3,</span></span>
<span class="line"><span>    counter.Reset.NewlinesReset,</span></span>
<span class="line"><span>)</span></span></code></pre></div><h4 id="調用函數" tabindex="-1">調用函數 <a class="header-anchor" href="#調用函數" aria-label="Permalink to “調用函數”">​</a></h4><p>最終的收益終於來了。檢查這個字符串是否至少有三個 “c” 字符：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&gt;&gt;&gt; cntr.has_count(&quot;hello-c-c-c-goodbye&quot;)</span></span>
<span class="line"><span>True</span></span></code></pre></div><p>添加一個換行符會觸發剩餘操作，這裏沒有插入換行符的三個 “c” 字符：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&gt;&gt;&gt; cntr.has_count(&quot;hello-c-c-\\nc-goodbye&quot;)</span></span>
<span class="line"><span>False</span></span></code></pre></div><h3 id="使用-rust-和-python-很容易" tabindex="-1">使用 Rust 和 Python 很容易 <a class="header-anchor" href="#使用-rust-和-python-很容易" aria-label="Permalink to “使用 Rust 和 Python 很容易”">​</a></h3><p>我的目標是讓你相信將 Rust 和 Python 結合起來很簡單。我編寫了一些“粘合劑”代碼。Rust 和 Python 具有互補的優點和缺點。</p><p>Rust 非常適合高性能、安全的代碼。Rust 具有陡峭的學習曲線，對於快速原型解決方案而言可能有些笨拙。</p><p>Python 很容易入手，並支持非常緊密的迭代循環。Python 確實有一個“速度上限”。超過一定程度後，從 Python 中獲得更好的性能就更難了。</p><p>將它們結合起來完美無縫。在 Python 中進行原型設計，並將性能瓶頸移至 Rust 中。</p><p>使用 Maturin，你的開發和部署流程更容易進行。開發、構建並享受這一組合吧！</p><hr>`,96)),p("p",null,[s[1]||(s[1]=a("via: ",-1)),e(n,{href:"https://opensource.com/article/23/3/python-loves-rust"},{default:t(()=>[...s[0]||(s[0]=[a("https://opensource.com/article/23/3/python-loves-rust",-1)])]),_:1})]),p("p",null,[s[5]||(s[5]=a("作者：",-1)),e(n,{href:"https://opensource.com/users/moshez"},{default:t(()=>[...s[2]||(s[2]=[a("Moshe Zadka",-1)])]),_:1}),s[6]||(s[6]=a(" 選題：",-1)),e(n,{href:"https://github.com/lkxed/"},{default:t(()=>[...s[3]||(s[3]=[a("lkxed",-1)])]),_:1}),s[7]||(s[7]=a(" 譯者：ChatGPT 校對：",-1)),e(n,{href:"https://github.com/wxy"},{default:t(()=>[...s[4]||(s[4]=[a("wxy",-1)])]),_:1})]),p("p",null,[s[10]||(s[10]=a("本文由 ",-1)),e(n,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...s[8]||(s[8]=[a("LCTT",-1)])]),_:1}),s[11]||(s[11]=a(" 原創編譯，",-1)),e(n,{href:"https://linux.cn/"},{default:t(()=>[...s[9]||(s[9]=[a("Linux中國",-1)])]),_:1}),s[12]||(s[12]=a(" 榮譽推出",-1))])])}const R=i(c,[["render",d]]);export{P as __pageData,R as default};
